def get_level_lengths(levels: Any, sentinel: bool | object | str='') -> list[dict[int, int]]:
    if len(levels) == 0:
        return []
    control = [True] * len(levels[0])
    result = []
    for level in levels:
        last_index = 0
        lengths = {}
        for i, key in enumerate(level):
            if control[i] and key == sentinel:
